NOTES=[
N('___ the window, please.','Open','Emir cümlesi yalın fiille başlar.',{'Opens': 'Emirde fiile -s eklenmez.', 'To open': 'To open emir cümlesi değil, mastar biçimidir.'}),
N('___ run in the corridor.',"Don't","Olumsuz emir Don't ile kurulur.",{'Not': 'Not tek başına emirde olumsuzluk kurmaz.', 'No': 'No bir isim ya da sıfatla kullanılır, emir kurmaz.'}),
N('___ go to the park.',"Let's","Öneri için Let's kullanılır.",{'Let': "Let tek başına öneri kurmaz; Let's (let us) gerekir.", 'We': 'We özne olur; emir/öneri yapısında kullanılmaz.'}),
N('Please ___ quiet.','be','Emir cümlesinde be yalın hâlde kalır.',{'are': 'Emirde fiil çekimlenmez; are kullanılmaz.', 'to be': 'To be emirde kullanılmaz.'}),
N('___ forget your keys.',"Don't","Olumsuz emir Don't ile başlar.",{'Not': 'Not emirde olumsuzluk kurmaz.', "Doesn't": "Doesn't üçüncü tekil kişi için geniş zaman yardımcısıdır, emirde kullanılmaz."}),
N("Let's ___ a break.",'take',"Let's sonrası yalın fiil gelir.",{'to take': "Let's sonrası to kullanılmaz.", 'taking': "Let's sonrası -ing kullanılmaz."}),
N('___ careful with the hot tea.','Be','Emirde be yalın hâlde başa gelir.',{'Are': 'Emirde are kullanılmaz.', 'You be': 'Emirde özne yazılmaz.'}),
N("Let's ___ argue.",'not',"Olumsuz öneri Let's not ile kurulur.",{"don't": "Let's don't günlük konuşmada duyulsa da standart biçim Let's not'tır.", 'no': 'no bu yapıda kullanılmaz.'}),
N('___ sit down, please.','Do','Vurgulu emirde Do + yalın fiil kullanılır.',{'Does': 'Does emirde kullanılmaz.', 'Doing': 'Doing emir kurmaz.'}),
N('___ open the door to strangers.','Never','Never emirde doğrudan kullanılır.',{'Not ever': 'Not ever bu kalıpta doğal değildir.', "Don't never": 'Çift olumsuz yapılmaz.'}),
N('Please ___ your seats.','take','Emirde fiil yalın kalır.',{'takes': 'Emirde fiile -s eklenmez.', 'to take': 'Emirde to kullanılmaz.'}),
N('___ hurry, we have plenty of time.',"Don't","Olumsuz emir Don't ile başlar.",{'Not': 'Not emirde olumsuz kurmaz.', "Doesn't": "Doesn't emirde kullanılmaz."}),
N('Hangi cümle doğru?',"Don't touch the wires.",'Emirde özne yazılmaz ve to kullanılmaz.',{"You don't touch the wires.": 'Özne yazılırsa emir değil bildirme cümlesi olur.', "Don't to touch the wires.": "Don't sonrası to gelmez."}),
N('Hangi cümle doğru?',"Let's go to the cinema.","Let's + yalın fiil.",{"Let's to go to the cinema.": "Let's sonrası to kullanılmaz.", "Let's going to the cinema.": "Let's sonrası -ing kullanılmaz."}),
N('Hangi cümle doğru?','Open your books, please.','Emir yalın fiille başlar.',{'Opens your books, please.': 'Fiile -s eklenmez.', 'Please you open your books.': 'Emirde özne (you) yazılmaz.'}),
N('Hangi cümle doğru?',"Let's not be late.","Olumsuz öneri Let's not ile kurulur.",{"Let's don't be late.": "Standart biçim Let's not'tır.", "Don't let's be late.": "Don't let's kalıbı olağan değildir."}),
N('Hangi cümle doğru?','Be quiet, please.','Emirde be yalın kalır.',{'Are quiet, please.': 'Emirde are kullanılmaz.', 'Please to be quiet.': 'Please sonrası to kullanılmaz.'}),
N('Hangi cümle doğru?','Do come in and sit down.','Do + yalın fiil vurgu katar.',{'Do comes in and sit down.': 'Do sonrası -s eklenmez.', 'Do to come in and sit down.': 'Do sonrası to kullanılmaz.'}),
N('Hangi cümle doğru?','Never leave the door open at night.','Never emirde tek başına kullanılır.',{"Don't never leave the door open at night.": 'Çift olumsuz yapılmaz.', 'Never to leave the door open at night.': 'Never sonrası to kullanılmaz.'}),
N('Hangi cümle doğru?',"Let's wait here and see what happens.","Let's sonrası yalın fiil gelir.",{"Let's to wait here and see what happens.": "Let's sonrası to kullanılmaz.", "Let's waiting here and see what happens.": "Let's sonrası -ing kullanılmaz."}),
]
